import javax.xml.parsers.DocumentBuilderFactory;
import javax.xml.parsers.ParserConfigurationException;
import java.io.File;
import java.io.IOException;

public class ConfigService {

    /**
     * Validates the XML configuration file for well-formedness and then parses it into a DOM Document.
     *
     * @param configPath Path to the user-provided XML configuration file
     * @return Parsed org.w3c.dom.Document object
     */
    public org.w3c.dom.Document loadConfig(java.lang.String configPath) {
        // 1. Input validation
        if (configPath == null || configPath.trim().isEmpty()) {
            throw new IllegalArgumentException("Configuration path cannot be null or empty.");
        }

        File configFile = new File(configPath);
        if (!configFile.exists() || !configFile.isFile()) {
            throw new IllegalArgumentException("Configuration file not found: " + configPath);
        }

        // 2. Parse and validate XML into DOM Document securely
        // DocumentBuilder.parse() inherently checks for well-formedness.
        // We configure the factory with secure features to prevent XXE and other parser attacks.
        try {
            DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();
            dbf.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
            dbf.setFeature("http://xml.org/sax/features/external-general-entities", false);
            dbf.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
            dbf.setExpandEntityReferences(false);
            dbf.setNamespaceAware(true);

            DocumentBuilder db = dbf.newDocumentBuilder();
            return db.parse(configFile);
        } catch (ParserConfigurationException e) {
            throw new RuntimeException("Failed to configure the XML DocumentBuilder.", e);
        } catch (SAXException e) {
            throw new RuntimeException("XML validation failed: The configuration file is not well-formed.", e);
        } catch (IOException e) {
            throw new RuntimeException("I/O error occurred during XML parsing.", e);
        }
    }
}

